#[inductive(client_send)]
fn client_send_inductive(pre: Self,
    post: Self, j: nat, request: Request, cur_slot: bool)
{
    // Establish what changed
    assert(pre.clients.index(j) == Client::Idle);
    assert(post.clients.index(j) == Client::Waiting{rid: request.rid});
    assert(pre.slots.index(j) == cur_slot);
    assert(post.slots.index(j) == true);
    assert(forall |i: nat| pre.valid_idx(i) && i != j ==> 
        pre.clients.index(i) == post.clients.index(i));
    assert(forall |i: nat| pre.valid_idx(i) && i != j ==> 
        pre.slots.index(i) == post.slots.index(i));
    assert(post.requests.dom() == pre.requests.dom().insert(j));
    assert(post.requests.index(j) == request);
    assert(forall |i: nat| pre.valid_idx(i) && i != j && pre.requests.dom().contains(i) ==>
        post.requests.index(i) == pre.requests.index(i));
    assert(post.responses.dom() == pre.responses.dom());
    assert(post.combiner == pre.combiner);

    // Prove not_waiting_inv
    assert(forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() ==>
        !post.slots.index(i)) by {
        assert forall |i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() 
        implies !post.slots.index(i) by {
            if i == j {
                // Client j is now Waiting, not Idle, so antecedent is false
            } else {
                // For i != j, clients and slots unchanged
                assert(pre.clients.index(i) == post.clients.index(i));
                assert(pre.slots.index(i) == post.slots.index(i));
                // By pre invariant: if pre.clients.index(i).is_Idle() then !pre.slots.index(i)
                // Since post.clients.index(i).is_Idle() iff pre.clients.index(i).is_Idle():
                if post.clients.index(i).is_Idle() {  // assumption
                    assert(pre.clients.index(i).is_Idle());
                    // By pre invariant:
                    assert(!pre.slots.index(i));
                    // Since slots unchanged:
                    assert(!post.slots.index(i));
                }
            }
        }
    };

    // Prove waiting_inv
    assert(forall |i: nat| #[trigger] post.client_waiting(i) ==>
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)) by {
        assert forall |i: nat| #[trigger] post.client_waiting(i) 
        implies post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
            if i == j {
                // Client j is now Waiting and we just stored its request
                assert(post.request_stored(j));
            } else {
                // i != j: client state unchanged
                assert(pre.clients.index(i) == post.clients.index(i));
                assert(pre.client_waiting(i) == post.client_waiting(i));
                // By pre invariant: if pre.client_waiting(i) then pre satisfies disjunction
                if post.client_waiting(i) {  // assumption 
                    assert(pre.client_waiting(i));
                    assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
                    // Storage and combiner state unchanged for i != j
                    assert(post.request_stored(i) == pre.request_stored(i));
                    assert(post.response_stored(i) == pre.response_stored(i));
                    assert(post.combiner_has(i) == pre.combiner_has(i));
                }
            }
        }
    };

    // Prove request_stored_inv
    assert(forall |i: nat| #[trigger] post.request_stored(i) ==>
        post.client_waiting(i)
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && post.slots.index(i)) by {
        assert forall |i: nat| #[trigger] post.request_stored(i) 
        implies post.client_waiting(i)
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && post.slots.index(i) by {
            if i == j {
                // Just stored the request for client j
                assert(post.request_stored(j));
                assert(post.client_waiting(j));
                assert(post.requests.index(j).rid == request.rid);
                assert(post.clients.index(j).get_Waiting_rid() == request.rid);
                assert(post.slots.index(j));
            } else {
                // i != j: request storage unchanged
                assert(post.request_stored(i) == pre.request_stored(i));
                if post.request_stored(i) {  // assumption
                    assert(pre.request_stored(i));
                    // By pre invariant:
                    assert(pre.client_waiting(i));
                    assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(pre.slots.index(i));
                    // Client state unchanged for i != j
                    assert(post.client_waiting(i) == pre.client_waiting(i));
                    assert(post.requests.index(i).rid == pre.requests.index(i).rid);
                    assert(post.clients.index(i) == pre.clients.index(i));
                    assert(post.slots.index(i) == pre.slots.index(i));
                    assert(post.client_waiting(i));
                    assert(post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid());
                    assert(post.slots.index(i));
                }
            }
        }
    };

    // Prove response_stored_inv
    assert(forall |i: nat| #[trigger] post.response_stored(i) ==>
        post.client_waiting(i)
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && !post.slots.index(i)) by {
        assert forall |i: nat| #[trigger] post.response_stored(i) 
        implies post.client_waiting(i)
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && !post.slots.index(i) by {
            // Storage unchanged for responses
            assert(post.responses.dom() == pre.responses.dom());
            assert(forall |k: nat| pre.valid_idx(k) && pre.responses.dom().contains(k) ==>
                post.responses.index(k) == pre.responses.index(k));
            if post.response_stored(i) {  // assumption
                assert(pre.response_stored(i));
                // By pre invariant:
                assert(pre.client_waiting(i));
                assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.slots.index(i));
                // Client state and slot unchanged for i
                assert(post.client_waiting(i) == pre.client_waiting(i));
                assert(post.responses.index(i).rid == pre.responses.index(i).rid);
                assert(post.clients.index(i) == pre.clients.index(i));
                assert(post.slots.index(i) == pre.slots.index(i));
                assert(post.client_waiting(i));
                assert(post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid());
                assert(!post.slots.index(i));
            }
        }
    };

    // Prove combiner_has_inv
    assert(forall |i: nat| #[trigger] post.combiner_has(i) ==>
        post.client_waiting(i)
        && post.slots.index(i)
        && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
        && !post.request_stored(i)) by {
        assert forall |i: nat| #[trigger] post.combiner_has(i) 
        implies post.client_waiting(i)
        && post.slots.index(i)
        && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
        && !post.request_stored(i) by {
            // Combiner state unchanged
            assert(post.combiner == pre.combiner);
            assert(post.combiner_has(i) == pre.combiner_has(i));
            if post.combiner_has(i) {  // assumption
                assert(pre.combiner_has(i));
                // By pre invariant:
                assert(pre.client_waiting(i));
                assert(pre.slots.index(i));
                assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                assert(!pre.request_stored(i));
                // Client state and slot unchanged for i
                assert(post.client_waiting(i) == pre.client_waiting(i));
                assert(post.slots.index(i) == pre.slots.index(i));
                assert(post.combiner_rid(i) == pre.combiner_rid(i));
                assert(post.clients.index(i) == pre.clients.index(i));
                assert(post.request_stored(i) == pre.request_stored(i));
                assert(post.client_waiting(i));
                assert(post.slots.index(i));
                assert(post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid());
                assert(!post.request_stored(i));
            }
        }
    };
}

