    assert(forall |i: nat| pre.valid_idx(i) && i != j ==> pre.clients.index(i) == post.clients.index(i));
    assert(forall |i: nat| pre.valid_idx(i) && i != j ==> pre.slots.index(i) == post.slots.index(i));

    // Storage changes only at index j  
